using System;
using System.Collections.Generic;
using System.Globalization;
using System.Linq;

namespace DesktopAccounts {
    public sealed class LanguageChoice {
        public string Id { get; private set; }
        public string Name { get; private set; }
        public LanguageChoice(string id, string name) { Id = id; Name = name; }
        public override string ToString() { return Name; }
    }
    public sealed class UiText {
        public static readonly LanguageChoice[] Languages = {
            new LanguageChoice("en", "English"), new LanguageChoice("zh-Hans", "简体中文"),
            new LanguageChoice("zh-Hant", "繁體中文"), new LanguageChoice("fr", "Français"), new LanguageChoice("ja", "日本語")
        };
        readonly int index;
        public string Language { get; private set; }
        public UiText(string language) { Language = Normalize(language); index = Array.FindIndex(Languages, item => item.Id == Language); }
        public static string Normalize(string value) { return Languages.Any(item => item.Id == value) ? value : "en"; }
        public string this[string key] { get { string[] row; if (!Rows.TryGetValue(key, out row)) throw new ArgumentException("Unknown UI text key."); return row[index]; } }
        public string F(string key, params object[] values) { return String.Format(CultureInfo.InvariantCulture, this[key], values); }
        public static bool Complete { get { return Rows.Values.All(row => row.Length == Languages.Length && row.All(value => !String.IsNullOrWhiteSpace(value))); } }
        public static IEnumerable<string> Keys { get { return Rows.Keys; } }
